// Entry point: Node.js port of test20.py.
// Usage: node test20.mjs --a '<instance JSON>' --b '<schema JSON>'

import {
  Draft4Validator,
  Draft6Validator,
  Draft7Validator,
  Draft201909Validator,
  Draft202012Validator,
  validator_for,
} from "./lib/drafts.mjs";
import { FormatChecker } from "./lib/formatChecker.mjs";
import { ErrorTree } from "./lib/errorTree.mjs";

function usageError(message) {
  process.stderr.write("usage: test20.mjs [-h] --a A --b B\n");
  process.stderr.write(`test20.mjs: error: ${message}\n`);
  process.exit(2);
}

// Mimics argparse for two required string options, supporting both
// "--name value" and "--name=value" forms.
function parseArgs(argv) {
  const result = {};
  for (let i = 2; i < argv.length; i += 1) {
    let arg = argv[i];
    let value;
    if (arg.startsWith("--") && arg.includes("=")) {
      const eq = arg.indexOf("=");
      value = arg.slice(eq + 1);
      arg = arg.slice(0, eq);
    } else {
      i += 1;
      if (i >= argv.length) {
        usageError(`argument ${arg}: expected one argument`);
      }
      value = argv[i];
    }
    if (arg === "--a") result.a = value;
    else if (arg === "--b") result.b = value;
    else if (arg === "-h" || arg === "--help") {
      process.stdout.write("usage: test20.mjs [-h] --a A --b B\n");
      process.exit(0);
    } else {
      usageError(`unrecognized arguments: ${arg}`);
    }
  }
  const missing = [];
  if (result.a === undefined) missing.push("--a");
  if (result.b === undefined) missing.push("--b");
  if (missing.length > 0) {
    usageError(`the following arguments are required: ${missing.join(", ")}`);
  }
  return result;
}

function pyBool(value) {
  return value ? "True" : "False";
}

const args = parseArgs(process.argv);

const instance = JSON.parse(args.a);
const schema = JSON.parse(args.b);

// Create all version validators
const v4 = new Draft4Validator(schema);
const v6 = new Draft6Validator(schema);
const v7 = new Draft7Validator(schema);
const v2019 = new Draft201909Validator(schema);
const v2020 = new Draft202012Validator(schema);

// Validate with each version
const valid_v4 = v4.is_valid(instance);
const valid_v6 = v6.is_valid(instance);
const valid_v7 = v7.is_valid(instance);
const valid_2019 = v2019.is_valid(instance);
const valid_2020 = v2020.is_valid(instance);

// Get error counts for each
const errs_v4 = [...v4.iter_errors(instance)].length;
const errs_v6 = [...v6.iter_errors(instance)].length;
const errs_v7 = [...v7.iter_errors(instance)].length;
const errs_2019 = [...v2019.iter_errors(instance)].length;
const errs_2020 = [...v2020.iter_errors(instance)].length;

// Check schemas
const check_v4 = v4.check_schema(schema);
const check_v6 = v6.check_schema(schema);
const check_v7 = v7.check_schema(schema);
const check_2019 = v2019.check_schema(schema);
const check_2020 = v2020.check_schema(schema);

// Build error trees
const errors_v7 = [...v7.iter_errors(instance)];
const tree_v7 = new ErrorTree(errors_v7);

// Get format checker
const format_checker = new FormatChecker();
const checker_count = Object.keys(format_checker.checkers).length;

// Determine validator for schema
const auto_validator = validator_for(schema);

// Evolve validators
const evolved_v7 = v7.evolve({ schema });
const evolved_valid = evolved_v7.is_valid(instance);

console.log(pyBool(valid_v4));
console.log(pyBool(valid_v6));
console.log(pyBool(valid_v7));
console.log(pyBool(valid_2019));
console.log(pyBool(valid_2020));
console.log(errs_v4);
console.log(errs_v6);
console.log(errs_v7);
console.log(errs_2019);
console.log(errs_2020);
console.log(check_v4 === undefined ? "None" : check_v4);
console.log(check_v6 === undefined ? "None" : check_v6);
console.log(check_v7 === undefined ? "None" : check_v7);
console.log(check_2019 === undefined ? "None" : check_2019);
console.log(check_2020 === undefined ? "None" : check_2020);
console.log(tree_v7.total_errors);
console.log(checker_count);
console.log(auto_validator.name);
console.log(pyBool(evolved_valid));
console.log(pyBool(valid_v7 === evolved_valid));

// JSON parsing with Python semantics (json.loads).
//
// The crucial difference from JSON.parse: Python distinguishes int from float
// by the literal's syntax, and jsonschema's "integer" type check only accepts
// genuine ints (3.0 is NOT an integer). JSON.parse loses that distinction
// (3.0 -> 3). This parser boxes every number written with a fraction or
// exponent into a `Number` object so the type checker can tell floats apart
// from ints. Boxed numbers behave like primitives for arithmetic and
// comparisons thanks to valueOf coercion; use `unwrap` / `isNumber` from
// jtype.mjs when a primitive is needed.
//
// Like json.loads, NaN / Infinity / -Infinity literals are accepted.

export function isBoxedNumber(value) {
  return value instanceof Number;
}

export function parseJSON(text) {
  let pos = 0;
  const len = text.length;

  function error(message) {
    throw new SyntaxError(`${message}: at position ${pos}`);
  }

  function skipWhitespace() {
    while (pos < len) {
      const ch = text[pos];
      if (ch === " " || ch === "\t" || ch === "\n" || ch === "\r") pos += 1;
      else break;
    }
  }

  function parseValue() {
    skipWhitespace();
    if (pos >= len) error("Expecting value");
    const ch = text[pos];
    if (ch === "{") return parseObject();
    if (ch === "[") return parseArray();
    if (ch === '"') return parseString();
    if (ch === "t") return parseLiteral("true", true);
    if (ch === "f") return parseLiteral("false", false);
    if (ch === "n") return parseLiteral("null", null);
    if (ch === "N") return parseLiteral("NaN", new Number(NaN));
    if (ch === "I") return parseLiteral("Infinity", new Number(Infinity));
    if (ch === "-" || (ch >= "0" && ch <= "9")) return parseNumber();
    error("Expecting value");
    return undefined;
  }

  function parseLiteral(literal, value) {
    if (text.startsWith(literal, pos)) {
      pos += literal.length;
      return value;
    }
    error("Expecting value");
    return undefined;
  }

  function parseNumber() {
    const start = pos;
    if (text[pos] === "-") {
      pos += 1;
      if (text.startsWith("Infinity", pos)) {
        pos += "Infinity".length;
        return new Number(-Infinity);
      }
    }
    if (pos >= len || text[pos] < "0" || text[pos] > "9") {
      error("Invalid number");
    }
    if (text[pos] === "0") {
      pos += 1;
      if (pos < len && text[pos] >= "0" && text[pos] <= "9") {
        error("Invalid number (leading zero)");
      }
    } else {
      while (pos < len && text[pos] >= "0" && text[pos] <= "9") pos += 1;
    }
    let isFloat = false;
    if (text[pos] === ".") {
      isFloat = true;
      pos += 1;
      if (pos >= len || text[pos] < "0" || text[pos] > "9") error("Invalid number");
      while (pos < len && text[pos] >= "0" && text[pos] <= "9") pos += 1;
    }
    if (text[pos] === "e" || text[pos] === "E") {
      isFloat = true;
      pos += 1;
      if (text[pos] === "+" || text[pos] === "-") pos += 1;
      if (pos >= len || text[pos] < "0" || text[pos] > "9") error("Invalid number");
      while (pos < len && text[pos] >= "0" && text[pos] <= "9") pos += 1;
    }
    const raw = text.slice(start, pos);
    const value = Number(raw);
    return isFloat ? new Number(value) : value;
  }

  function parseString() {
    pos += 1; // opening quote
    let result = "";
    while (pos < len) {
      const ch = text[pos];
      if (ch === '"') {
        pos += 1;
        return result;
      }
      if (ch === "\\") {
        pos += 1;
        if (pos >= len) error("Unterminated string escape");
        const esc = text[pos];
        pos += 1;
        switch (esc) {
          case '"': result += '"'; break;
          case "\\": result += "\\"; break;
          case "/": result += "/"; break;
          case "b": result += "\b"; break;
          case "f": result += "\f"; break;
          case "n": result += "\n"; break;
          case "r": result += "\r"; break;
          case "t": result += "\t"; break;
          case "u": {
            const hex = text.slice(pos, pos + 4);
            if (!/^[0-9a-fA-F]{4}$/.test(hex)) error("Invalid \\uXXXX escape");
            let code = parseInt(hex, 16);
            pos += 4;
            if (code >= 0xd800 && code <= 0xdbff && text.slice(pos, pos + 2) === "\\u") {
              const hex2 = text.slice(pos + 2, pos + 6);
              if (/^[0-9a-fA-F]{4}$/.test(hex2)) {
                const low = parseInt(hex2, 16);
                if (low >= 0xdc00 && low <= 0xdfff) {
                  code = 0x10000 + ((code - 0xd800) << 10) + (low - 0xdc00);
                  pos += 6;
                }
              }
            }
            result += String.fromCodePoint(code);
            break;
          }
          default:
            error("Invalid escape character");
        }
      } else {
        result += ch;
        pos += 1;
      }
    }
    error("Unterminated string");
    return undefined;
  }

  function parseArray() {
    pos += 1; // [
    const arr = [];
    skipWhitespace();
    if (text[pos] === "]") {
      pos += 1;
      return arr;
    }
    for (;;) {
      arr.push(parseValue());
      skipWhitespace();
      if (text[pos] === ",") {
        pos += 1;
      } else if (text[pos] === "]") {
        pos += 1;
        return arr;
      } else {
        error("Expecting ',' delimiter");
      }
    }
  }

  function parseObject() {
    pos += 1; // {
    const obj = {};
    skipWhitespace();
    if (text[pos] === "}") {
      pos += 1;
      return obj;
    }
    for (;;) {
      skipWhitespace();
      if (text[pos] !== '"') error("Expecting property name enclosed in double quotes");
      const key = parseString();
      skipWhitespace();
      if (text[pos] !== ":") error("Expecting ':' delimiter");
      pos += 1;
      obj[key] = parseValue();
      skipWhitespace();
      if (text[pos] === ",") {
        pos += 1;
      } else if (text[pos] === "}") {
        pos += 1;
        return obj;
      } else {
        error("Expecting ',' delimiter");
      }
    }
  }

  const value = parseValue();
  skipWhitespace();
  if (pos !== len) error("Extra data");
  return value;
}

// JSON type detection helpers, mirroring Python jsonschema's type checks.
//
// Numbers parsed from float syntax (3.0, 1e2) are boxed `Number` objects (see
// pyjson.mjs) so that "integer" only matches genuine Python ints. Booleans are
// never numbers, matching jsonschema's exclusion of Python's bool (a subclass
// of int there).

export function isNumber(value) {
  return typeof value === "number" || value instanceof Number;
}

export function unwrap(value) {
  return value instanceof Number ? value.valueOf() : value;
}

export function jtype(value) {
  if (value === null) return "null";
  if (Array.isArray(value)) return "array";
  if (typeof value === "number") return Number.isInteger(value) ? "integer" : "number";
  if (value instanceof Number) return "number"; // Python float, even if integral
  const t = typeof value;
  if (t === "string") return "string";
  if (t === "boolean") return "boolean";
  return "object";
}

export function isType(value, type) {
  switch (type) {
    case "null":
      return value === null;
    case "boolean":
      return typeof value === "boolean";
    case "string":
      return typeof value === "string";
    case "array":
      return Array.isArray(value);
    case "object":
      return value !== null && typeof value === "object" && !Array.isArray(value) && !(value instanceof Number);
    case "number":
      return isNumber(value);
    case "integer":
      // Only genuine ints; floats with zero fractional part do not qualify.
      return typeof value === "number" && Number.isInteger(value);
    default:
      return false;
  }
}

// Number of characters as Python's len(str) counts them (code points).
export function codePointLength(str) {
  let n = 0;
  for (const _ch of str) n += 1;
  return n;
}

// Deep equality with Python-flavoured semantics as used by jsonschema for
// `enum`, `const` and `uniqueItems`:
//   - numbers compare by numeric value (1 == 1.0, boxed floats unwrapped),
//   - booleans are NOT equal to numbers (jsonschema "unbools" before
//     comparing, so True does not equal 1),
//   - arrays compare element-wise, objects compare key-wise (order-free).

import { jtype, unwrap } from "./jtype.mjs";

function isNumeric(t) {
  return t === "number" || t === "integer";
}

export function pyEqual(a, b) {
  const ta = jtype(a);
  const tb = jtype(b);

  if (isNumeric(ta) && isNumeric(tb)) return unwrap(a) === unwrap(b);
  if (ta !== tb) return false;

  switch (ta) {
    case "array": {
      if (a.length !== b.length) return false;
      for (let i = 0; i < a.length; i += 1) {
        if (!pyEqual(a[i], b[i])) return false;
      }
      return true;
    }
    case "object": {
      const ka = Object.keys(a);
      const kb = Object.keys(b);
      if (ka.length !== kb.length) return false;
      for (const key of ka) {
        if (!Object.prototype.hasOwnProperty.call(b, key)) return false;
        if (!pyEqual(a[key], b[key])) return false;
      }
      return true;
    }
    default:
      return a === b;
  }
}

// ValidationError: mirrors jsonschema.exceptions.ValidationError.
// Observable attributes: `path` (instance location, used by ErrorTree),
// `validator` (the keyword that failed; ErrorTree keys errors on it) and
// `context` (sub-errors of anyOf/oneOf failures, not part of the tree).

export class ValidationError extends Error {
  constructor(message, path = [], validator = "", context = []) {
    super(message);
    this.name = "ValidationError";
    this.message = message;
    this.path = path;
    this.validator = validator;
    this.context = context;
  }
}

// SchemaError: raised by check_schema (and by un-crawlable schemas, mirroring
// the `referencing` library failures) when a schema is invalid. The Python
// program crashes with a traceback in these cases; the entry point exits
// non-zero without writing to stdout, matching that observable behaviour.

export class SchemaError extends Error {
  constructor(message) {
    super(message);
    this.name = "SchemaError";
  }
}

// Keyword validation engine.
//
// `descend(v, instance, schema, path)` yields one ValidationError per failed
// keyword, descending into subschemas exactly the way the Python `jsonschema`
// package's `iter_errors` does:
//   - allOf yields the errors of each failing subschema directly,
//   - anyOf / oneOf / not yield a single error (with sub-errors as context),
//   - required / dependent* yield one error per missing property,
//   - additionalProperties: false yields a single error for all extras,
//   - propertyNames yields the name-schema errors per property (at the
//     instance's own path, as jsonschema does not extend the path there),
//   - contains yields a single error.
//
// Every error carries the keyword name as `validator`; ErrorTree keys node
// errors on it. Draft differences are driven by flags on `v.config`.

import { isType, jtype, isNumber, unwrap, codePointLength } from "./jtype.mjs";
import { pyEqual } from "./pyEqual.mjs";
import { ValidationError } from "./errors.mjs";

// Resolve a same-document JSON Pointer reference ("#/definitions/foo", "#").
export function resolvePointer(root, ref) {
  if (ref === "#" || ref === "") return root;
  if (!ref.startsWith("#/")) {
    throw new Error(`Unresolvable JSON reference: ${ref}`);
  }
  let node = root;
  for (const rawSeg of ref.slice(2).split("/")) {
    const seg = decodeURIComponent(rawSeg).replace(/~1/g, "/").replace(/~0/g, "~");
    if (node === null || typeof node !== "object") {
      throw new Error(`Unresolvable JSON reference: ${ref}`);
    }
    node = Array.isArray(node) ? node[Number(seg)] : node[seg];
    if (node === undefined) {
      throw new Error(`Unresolvable JSON reference: ${ref}`);
    }
  }
  return node;
}

function subErrors(v, instance, schema, path) {
  return [...descend(v, instance, schema, path)];
}

function subIsValid(v, instance, schema, path) {
  return descend(v, instance, schema, path).next().done;
}

export function* descend(v, instance, schema, path) {
  if (schema === true) return;
  if (schema === false) {
    yield new ValidationError("False schema does not allow the instance", path, "falseSchema");
    return;
  }
  const cfg = v.config;

  // $ref: in drafts 4-7 it replaces all sibling keywords; from 2019-09 on it
  // is evaluated alongside them.
  if (typeof schema.$ref === "string") {
    const target = resolvePointer(v.schema, schema.$ref);
    yield* descend(v, instance, target, path);
    if (cfg.refReplacesSiblings) return;
  }

  yield* typeKeyword(schema, instance, path);

  if (schema.enum !== undefined) {
    if (!schema.enum.some((each) => pyEqual(each, instance))) {
      yield new ValidationError("instance is not one of the enum values", path, "enum");
    }
  }
  if (cfg.hasConst && schema.const !== undefined) {
    if (!pyEqual(schema.const, instance)) {
      yield new ValidationError("const mismatch", path, "const");
    }
  }

  yield* numericKeywords(cfg, schema, instance, path);
  yield* stringKeywords(schema, instance, path);
  yield* arrayKeywords(v, cfg, schema, instance, path);
  yield* objectKeywords(v, cfg, schema, instance, path);
  yield* applicatorKeywords(v, cfg, schema, instance, path);
}

function* typeKeyword(schema, instance, path) {
  if (schema.type === undefined) return;
  const types = Array.isArray(schema.type) ? schema.type : [schema.type];
  if (!types.some((t) => isType(instance, t))) {
    yield new ValidationError(
      `${JSON.stringify(instance)} is not of type ${types.map((t) => `'${t}'`).join(", ")}`,
      path,
      "type",
    );
  }
}

function* numericKeywords(cfg, schema, instance, path) {
  if (!isNumber(instance)) return;
  const num = unwrap(instance);

  if (schema.multipleOf !== undefined) {
    const dB = schema.multipleOf;
    const dBNum = unwrap(dB);
    let failed;
    if (dB instanceof Number || !Number.isInteger(dBNum)) {
      // Python: isinstance(dB, float) -> quotient = instance / dB;
      // failed = int(quotient) != quotient
      const quotient = num / dBNum;
      failed = Math.trunc(quotient) !== quotient;
    } else {
      failed = num % dBNum !== 0;
    }
    if (failed) {
      yield new ValidationError(`${num} is not a multiple of ${dBNum}`, path, "multipleOf");
    }
  }

  if (cfg.exclusiveIsNumber) {
    // Draft 6+: exclusiveMinimum / exclusiveMaximum are numbers.
    if (schema.exclusiveMinimum !== undefined && num <= unwrap(schema.exclusiveMinimum)) {
      yield new ValidationError("less than or equal to the exclusive minimum", path, "exclusiveMinimum");
    }
    if (schema.minimum !== undefined && num < unwrap(schema.minimum)) {
      yield new ValidationError(`${num} is less than the minimum of ${unwrap(schema.minimum)}`, path, "minimum");
    }
    if (schema.exclusiveMaximum !== undefined && num >= unwrap(schema.exclusiveMaximum)) {
      yield new ValidationError("greater than or equal to the exclusive maximum", path, "exclusiveMaximum");
    }
    if (schema.maximum !== undefined && num > unwrap(schema.maximum)) {
      yield new ValidationError(`${num} is greater than the maximum of ${unwrap(schema.maximum)}`, path, "maximum");
    }
  } else {
    // Draft 4: exclusiveMinimum / exclusiveMaximum are boolean modifiers.
    if (schema.minimum !== undefined) {
      const exclusive = schema.exclusiveMinimum === true;
      const min = unwrap(schema.minimum);
      if (exclusive ? num <= min : num < min) {
        yield new ValidationError(`${num} is less than the minimum of ${min}`, path, "minimum");
      }
    }
    if (schema.maximum !== undefined) {
      const exclusive = schema.exclusiveMaximum === true;
      const max = unwrap(schema.maximum);
      if (exclusive ? num >= max : num > max) {
        yield new ValidationError(`${num} is greater than the maximum of ${max}`, path, "maximum");
      }
    }
  }
}

function* stringKeywords(schema, instance, path) {
  if (typeof instance !== "string") return;
  if (schema.maxLength !== undefined && codePointLength(instance) > schema.maxLength) {
    yield new ValidationError(`${JSON.stringify(instance)} is too long`, path, "maxLength");
  }
  if (schema.minLength !== undefined && codePointLength(instance) < schema.minLength) {
    yield new ValidationError(`${JSON.stringify(instance)} is too short`, path, "minLength");
  }
  if (schema.pattern !== undefined) {
    const re = new RegExp(schema.pattern);
    if (!re.test(instance)) {
      yield new ValidationError(`${JSON.stringify(instance)} does not match ${JSON.stringify(schema.pattern)}`, path, "pattern");
    }
  }
}

function* arrayKeywords(v, cfg, schema, instance, path) {
  if (!Array.isArray(instance)) return;

  if (schema.maxItems !== undefined && instance.length > schema.maxItems) {
    yield new ValidationError("too many items", path, "maxItems");
  }
  if (schema.minItems !== undefined && instance.length < schema.minItems) {
    yield new ValidationError("too few items", path, "minItems");
  }
  if (schema.uniqueItems === true) {
    let dup = false;
    outer: for (let i = 0; i < instance.length; i += 1) {
      for (let j = i + 1; j < instance.length; j += 1) {
        if (pyEqual(instance[i], instance[j])) {
          dup = true;
          break outer;
        }
      }
    }
    if (dup) {
      yield new ValidationError("has non-unique elements", path, "uniqueItems");
    }
  }

  if (cfg.prefixItems) {
    // Draft 2020-12: prefixItems is the tuple form, items applies to the rest.
    const prefix = Array.isArray(schema.prefixItems) ? schema.prefixItems : [];
    for (let i = 0; i < Math.min(prefix.length, instance.length); i += 1) {
      yield* descend(v, instance[i], prefix[i], path.concat(i));
    }
    if (schema.items !== undefined && instance.length > prefix.length) {
      for (let i = prefix.length; i < instance.length; i += 1) {
        yield* descend(v, instance[i], schema.items, path.concat(i));
      }
    }
  } else if (schema.items !== undefined) {
    if (Array.isArray(schema.items)) {
      // Drafts 4 - 2019-09 tuple form (unreachable for schemas that survived
      // construction in 2020-12, where an array here crashes the crawl).
      const tuple = schema.items;
      for (let i = 0; i < Math.min(tuple.length, instance.length); i += 1) {
        yield* descend(v, instance[i], tuple[i], path.concat(i));
      }
      if (instance.length > tuple.length && schema.additionalItems !== undefined) {
        if (schema.additionalItems === false) {
          yield new ValidationError("Additional items are not allowed", path, "additionalItems");
        } else if (schema.additionalItems !== true) {
          for (let i = tuple.length; i < instance.length; i += 1) {
            yield* descend(v, instance[i], schema.additionalItems, path.concat(i));
          }
        }
      }
    } else {
      for (let i = 0; i < instance.length; i += 1) {
        yield* descend(v, instance[i], schema.items, path.concat(i));
      }
    }
  }

  if (cfg.hasContains && schema.contains !== undefined) {
    let matches = 0;
    for (let i = 0; i < instance.length; i += 1) {
      if (subIsValid(v, instance[i], schema.contains, path.concat(i))) matches += 1;
    }
    if (cfg.hasMinMaxContains) {
      const minContains = schema.minContains === undefined ? 1 : schema.minContains;
      const maxContains = schema.maxContains;
      if (matches < minContains) {
        yield new ValidationError("Too few items match the given schema", path, "contains");
      } else if (maxContains !== undefined && matches > maxContains) {
        yield new ValidationError("Too many items match the given schema", path, "maxContains");
      }
    } else if (matches === 0) {
      yield new ValidationError("does not contain items matching the given schema", path, "contains");
    }
  }

  if (cfg.hasUnevaluated && schema.unevaluatedItems !== undefined) {
    const evaluated = findEvaluatedItemIndexes(v, instance, schema);
    const extras = [];
    for (let i = 0; i < instance.length; i += 1) {
      if (!evaluated.has(i)) extras.push(i);
    }
    if (extras.length > 0) {
      if (schema.unevaluatedItems === false) {
        yield new ValidationError("Unevaluated items are not allowed", path, "unevaluatedItems");
      } else if (schema.unevaluatedItems !== true) {
        for (const i of extras) {
          yield* descend(v, instance[i], schema.unevaluatedItems, path.concat(i));
        }
      }
    }
  }
}

function* objectKeywords(v, cfg, schema, instance, path) {
  if (!isType(instance, "object")) return;

  if (schema.maxProperties !== undefined && Object.keys(instance).length > schema.maxProperties) {
    yield new ValidationError("has too many properties", path, "maxProperties");
  }
  if (schema.minProperties !== undefined && Object.keys(instance).length < schema.minProperties) {
    yield new ValidationError("does not have enough properties", path, "minProperties");
  }

  if (Array.isArray(schema.required)) {
    for (const name of schema.required) {
      if (!Object.prototype.hasOwnProperty.call(instance, name)) {
        yield new ValidationError(`'${name}' is a required property`, path, "required");
      }
    }
  }

  const properties = isType(schema.properties, "object") ? schema.properties : {};
  const patterns = isType(schema.patternProperties, "object") ? schema.patternProperties : {};

  for (const [name, subschema] of Object.entries(properties)) {
    if (Object.prototype.hasOwnProperty.call(instance, name)) {
      yield* descend(v, instance[name], subschema, path.concat(name));
    }
  }
  for (const [pattern, subschema] of Object.entries(patterns)) {
    const re = new RegExp(pattern);
    for (const name of Object.keys(instance)) {
      if (re.test(name)) {
        yield* descend(v, instance[name], subschema, path.concat(name));
      }
    }
  }

  if (schema.additionalProperties !== undefined) {
    const extras = Object.keys(instance).filter(
      (name) =>
        !Object.prototype.hasOwnProperty.call(properties, name) &&
        !Object.keys(patterns).some((pattern) => new RegExp(pattern).test(name)),
    );
    if (extras.length > 0) {
      if (schema.additionalProperties === false) {
        yield new ValidationError("Additional properties are not allowed", path, "additionalProperties");
      } else if (schema.additionalProperties !== true) {
        for (const name of extras) {
          yield* descend(v, instance[name], schema.additionalProperties, path.concat(name));
        }
      }
    }
  }

  if (cfg.hasPropertyNames && schema.propertyNames !== undefined) {
    for (const name of Object.keys(instance)) {
      // jsonschema does not extend the instance path for propertyNames.
      yield* descend(v, name, schema.propertyNames, path);
    }
  }

  if (cfg.hasDependencies && isType(schema.dependencies, "object")) {
    for (const [name, dependency] of Object.entries(schema.dependencies)) {
      if (!Object.prototype.hasOwnProperty.call(instance, name)) continue;
      if (Array.isArray(dependency)) {
        for (const dep of dependency) {
          if (!Object.prototype.hasOwnProperty.call(instance, dep)) {
            yield new ValidationError(`'${dep}' is a dependency of '${name}'`, path, "dependencies");
          }
        }
      } else {
        yield* descend(v, instance, dependency, path);
      }
    }
  }

  if (cfg.hasDependents) {
    if (isType(schema.dependentRequired, "object")) {
      for (const [name, deps] of Object.entries(schema.dependentRequired)) {
        if (!Object.prototype.hasOwnProperty.call(instance, name)) continue;
        for (const dep of deps) {
          if (!Object.prototype.hasOwnProperty.call(instance, dep)) {
            yield new ValidationError(`'${dep}' is a dependency of '${name}'`, path, "dependentRequired");
          }
        }
      }
    }
    if (isType(schema.dependentSchemas, "object")) {
      for (const [name, subschema] of Object.entries(schema.dependentSchemas)) {
        if (!Object.prototype.hasOwnProperty.call(instance, name)) continue;
        yield* descend(v, instance, subschema, path);
      }
    }
  }

  if (cfg.hasUnevaluated && schema.unevaluatedProperties !== undefined) {
    const evaluated = findEvaluatedPropertyKeys(v, instance, schema);
    const extras = Object.keys(instance).filter((name) => !evaluated.has(name));
    if (extras.length > 0) {
      if (schema.unevaluatedProperties === false) {
        yield new ValidationError("Unevaluated properties are not allowed", path, "unevaluatedProperties");
      } else if (schema.unevaluatedProperties !== true) {
        for (const name of extras) {
          yield* descend(v, instance[name], schema.unevaluatedProperties, path.concat(name));
        }
      }
    }
  }
}

function* applicatorKeywords(v, cfg, schema, instance, path) {
  if (Array.isArray(schema.allOf)) {
    for (let i = 0; i < schema.allOf.length; i += 1) {
      yield* descend(v, instance, schema.allOf[i], path);
    }
  }

  if (Array.isArray(schema.anyOf)) {
    const context = [];
    let valid = false;
    for (const subschema of schema.anyOf) {
      const errs = subErrors(v, instance, subschema, path);
      if (errs.length === 0) {
        valid = true;
        break;
      }
      context.push(...errs);
    }
    if (!valid) {
      yield new ValidationError("is not valid under any of the given schemas", path, "anyOf", context);
    }
  }

  if (Array.isArray(schema.oneOf)) {
    const context = [];
    let valids = 0;
    for (const subschema of schema.oneOf) {
      const errs = subErrors(v, instance, subschema, path);
      if (errs.length === 0) valids += 1;
      else context.push(...errs);
    }
    if (valids !== 1) {
      yield new ValidationError("is not valid under exactly one of the given schemas", path, "oneOf", context);
    }
  }

  if (schema.not !== undefined) {
    if (subIsValid(v, instance, schema.not, path)) {
      yield new ValidationError("should not be valid under the given schema", path, "not");
    }
  }

  if (cfg.hasIfThenElse && schema.if !== undefined) {
    if (subIsValid(v, instance, schema.if, path)) {
      if (schema.then !== undefined) {
        yield* descend(v, instance, schema.then, path);
      }
    } else if (schema.else !== undefined) {
      yield* descend(v, instance, schema.else, path);
    }
  }
}

// --- "evaluated" annotation tracking for unevaluated* keywords -------------

function mergeInto(target, source) {
  for (const item of source) target.add(item);
}

function findEvaluatedPropertyKeys(v, instance, schema, seen = new Set()) {
  const evaluated = new Set();
  if (!isType(schema, "object")) return evaluated;
  if (seen.has(schema)) return evaluated;
  seen.add(schema);

  if (typeof schema.$ref === "string") {
    mergeInto(evaluated, findEvaluatedPropertyKeys(v, instance, resolvePointer(v.schema, schema.$ref), seen));
  }
  if (isType(schema.properties, "object")) {
    for (const name of Object.keys(schema.properties)) {
      if (Object.prototype.hasOwnProperty.call(instance, name)) evaluated.add(name);
    }
  }
  if (isType(schema.patternProperties, "object")) {
    for (const pattern of Object.keys(schema.patternProperties)) {
      const re = new RegExp(pattern);
      for (const name of Object.keys(instance)) {
        if (re.test(name)) evaluated.add(name);
      }
    }
  }
  if (schema.additionalProperties !== undefined) {
    for (const name of Object.keys(instance)) evaluated.add(name);
  }
  if (Array.isArray(schema.allOf)) {
    for (const sub of schema.allOf) {
      mergeInto(evaluated, findEvaluatedPropertyKeys(v, instance, sub, seen));
    }
  }
  if (Array.isArray(schema.anyOf)) {
    for (const sub of schema.anyOf) {
      if (subIsValid(v, instance, sub, [])) {
        mergeInto(evaluated, findEvaluatedPropertyKeys(v, instance, sub, seen));
      }
    }
  }
  if (Array.isArray(schema.oneOf)) {
    for (const sub of schema.oneOf) {
      if (subIsValid(v, instance, sub, [])) {
        mergeInto(evaluated, findEvaluatedPropertyKeys(v, instance, sub, seen));
      }
    }
  }
  if (schema.if !== undefined) {
    if (subIsValid(v, instance, schema.if, [])) {
      mergeInto(evaluated, findEvaluatedPropertyKeys(v, instance, schema.if, seen));
      if (schema.then !== undefined) {
        mergeInto(evaluated, findEvaluatedPropertyKeys(v, instance, schema.then, seen));
      }
    } else if (schema.else !== undefined) {
      mergeInto(evaluated, findEvaluatedPropertyKeys(v, instance, schema.else, seen));
    }
  }
  if (isType(schema.dependentSchemas, "object")) {
    for (const [name, sub] of Object.entries(schema.dependentSchemas)) {
      if (Object.prototype.hasOwnProperty.call(instance, name)) {
        mergeInto(evaluated, findEvaluatedPropertyKeys(v, instance, sub, seen));
      }
    }
  }
  return evaluated;
}

function findEvaluatedItemIndexes(v, instance, schema, seen = new Set()) {
  const evaluated = new Set();
  if (!isType(schema, "object")) return evaluated;
  if (seen.has(schema)) return evaluated;
  seen.add(schema);

  const addAll = () => {
    for (let i = 0; i < instance.length; i += 1) evaluated.add(i);
  };

  if (typeof schema.$ref === "string") {
    mergeInto(evaluated, findEvaluatedItemIndexes(v, instance, resolvePointer(v.schema, schema.$ref), seen));
  }
  if (Array.isArray(schema.prefixItems)) {
    for (let i = 0; i < Math.min(schema.prefixItems.length, instance.length); i += 1) evaluated.add(i);
    if (schema.items !== undefined) addAll();
  } else if (Array.isArray(schema.items)) {
    for (let i = 0; i < Math.min(schema.items.length, instance.length); i += 1) evaluated.add(i);
    if (schema.additionalItems !== undefined) addAll();
  } else if (schema.items !== undefined) {
    addAll();
  }
  if (Array.isArray(schema.allOf)) {
    for (const sub of schema.allOf) {
      mergeInto(evaluated, findEvaluatedItemIndexes(v, instance, sub, seen));
    }
  }
  if (Array.isArray(schema.anyOf)) {
    for (const sub of schema.anyOf) {
      if (subIsValid(v, instance, sub, [])) {
        mergeInto(evaluated, findEvaluatedItemIndexes(v, instance, sub, seen));
      }
    }
  }
  if (Array.isArray(schema.oneOf)) {
    for (const sub of schema.oneOf) {
      if (subIsValid(v, instance, sub, [])) {
        mergeInto(evaluated, findEvaluatedItemIndexes(v, instance, sub, seen));
      }
    }
  }
  if (schema.if !== undefined) {
    if (subIsValid(v, instance, schema.if, [])) {
      mergeInto(evaluated, findEvaluatedItemIndexes(v, instance, schema.if, seen));
      if (schema.then !== undefined) {
        mergeInto(evaluated, findEvaluatedItemIndexes(v, instance, schema.then, seen));
      }
    } else if (schema.else !== undefined) {
      mergeInto(evaluated, findEvaluatedItemIndexes(v, instance, schema.else, seen));
    }
  }
  return evaluated;
}

// Meta-schema validation (check_schema) plus crawlability checks.
//
// The Python program constructs all five draft validators (which walks the
// schema with the `referencing` library) and then runs every draft's
// check_schema before printing anything. Any failure crashes the process with
// no stdout and a non-zero exit. Observable consequence: a schema survives
// only if it is valid under *all* five meta-schemas AND crawlable by every
// draft's resource walk. This module enforces that union, recursively:
//
//   - boolean schemas are only allowed where draft-04 permits them, i.e. in
//     `additionalItems` / `additionalProperties` (explicitly boolean-or-schema
//     there) and in keywords unknown to draft-04 (contains, if/then/else,
//     propertyNames, dependentSchemas, unevaluated*, $defs values, ...),
//     whose metas (draft-6+) accept booleans;
//   - `items` must be an object: draft-04's meta allows the array form, but
//     the 2020-12 resource crawl crashes on it ('list' object has no
//     attribute 'get');
//   - `prefixItems` must be an array (2020-12 meta), elements may be booleans;
//   - exclusiveMinimum / exclusiveMaximum can never appear (draft-04 requires
//     booleans, draft-6+ require numbers, so every occurrence fails one);
//   - keyword value shapes (types, non-negative integers, string arrays, ...).
//
// Unknown keywords are allowed, as in every meta-schema.

import { SchemaError } from "./errors.mjs";
import { isType, isNumber, unwrap } from "./jtype.mjs";

const VALID_TYPES = new Set(["array", "boolean", "integer", "null", "number", "object", "string"]);

function fail(message) {
  throw new SchemaError(message);
}

// Subschema position where only an object is acceptable (draft-04 known).
function checkObjectOnly(value, where) {
  if (!isType(value, "object")) {
    fail(`${JSON.stringify(value)} is not a valid schema (in ${where})`);
  }
  checkNode(value, where);
}

// Subschema position where an object or a boolean is acceptable.
function checkObjectOrBool(value, where) {
  if (typeof value === "boolean") return;
  checkObjectOnly(value, where);
}

function checkNonNegativeInteger(value, keyword) {
  // Python ints only; a float literal (boxed) is not of type 'integer'.
  if (typeof value !== "number" || !Number.isInteger(value) || value < 0) {
    fail(`${JSON.stringify(value)} is not valid for '${keyword}' (non-negative integer expected)`);
  }
}

function checkStringArray(value, keyword, { minItems }) {
  if (!Array.isArray(value)) {
    fail(`${JSON.stringify(value)} is not of type 'array' (in '${keyword}')`);
  }
  if (minItems !== undefined && value.length < minItems) {
    fail(`${JSON.stringify(value)} is too short (in '${keyword}')`);
  }
  const seen = new Set();
  for (const item of value) {
    if (typeof item !== "string") {
      fail(`${JSON.stringify(item)} is not of type 'string' (in '${keyword}')`);
    }
    if (seen.has(item)) {
      fail(`${JSON.stringify(value)} has non-unique elements (in '${keyword}')`);
    }
    seen.add(item);
  }
}

function checkSchemaMap(value, keyword, valueCheck) {
  if (!isType(value, "object")) {
    fail(`${JSON.stringify(value)} is not of type 'object' (in '${keyword}')`);
  }
  for (const [name, sub] of Object.entries(value)) {
    valueCheck(sub, `${keyword}.${name}`);
  }
}

function checkNode(schema, where) {
  for (const [keyword, value] of Object.entries(schema)) {
    switch (keyword) {
      case "type": {
        const types = Array.isArray(value) ? value : [value];
        if (Array.isArray(value)) {
          if (value.length < 1) fail("[] is too short (in 'type')");
          if (new Set(value).size !== value.length) {
            fail(`${JSON.stringify(value)} has non-unique elements (in 'type')`);
          }
        }
        for (const t of types) {
          if (typeof t !== "string" || !VALID_TYPES.has(t)) {
            fail(`${JSON.stringify(t)} is not a valid JSON type (in 'type')`);
          }
        }
        break;
      }
      case "enum":
        if (!Array.isArray(value) || value.length < 1) {
          fail(`${JSON.stringify(value)} is not a valid 'enum'`);
        }
        break;
      case "const":
      case "default":
      case "examples":
        break; // any value allowed
      case "multipleOf":
        if (!isNumber(value) || !(unwrap(value) > 0)) {
          fail(`${JSON.stringify(value)} is not valid for 'multipleOf'`);
        }
        break;
      case "maximum":
      case "minimum":
        if (!isNumber(value)) {
          fail(`${JSON.stringify(value)} is not of type 'number' (in '${keyword}')`);
        }
        break;
      case "exclusiveMaximum":
      case "exclusiveMinimum":
        // draft-04 demands boolean, draft-6+ demand number: no value can
        // satisfy every meta-schema the program checks against.
        fail(`${JSON.stringify(value)} is not valid for '${keyword}'`);
        break;
      case "maxLength":
      case "minLength":
      case "maxItems":
      case "minItems":
      case "maxProperties":
      case "minProperties":
      case "minContains":
      case "maxContains":
        checkNonNegativeInteger(value, keyword);
        break;
      case "uniqueItems":
      case "readOnly":
      case "writeOnly":
        if (typeof value !== "boolean") {
          fail(`${JSON.stringify(value)} is not of type 'boolean' (in '${keyword}')`);
        }
        break;
      case "pattern":
      case "format":
      case "$ref":
      case "$id":
      case "id":
      case "$schema":
      case "$comment":
      case "$anchor":
      case "$recursiveRef":
      case "$dynamicRef":
      case "title":
      case "description":
        if (typeof value !== "string") {
          fail(`${JSON.stringify(value)} is not of type 'string' (in '${keyword}')`);
        }
        break;
      case "items":
        // draft-04's meta permits the tuple (array) form, but the 2020-12
        // resource crawl crashes on it before anything is printed.
        if (Array.isArray(value)) {
          fail("array-form 'items' is not crawlable by the 2020-12 validator");
        }
        checkObjectOnly(value, keyword);
        break;
      case "prefixItems":
        // Only 2020-12 knows this keyword; its meta requires an array.
        if (!Array.isArray(value)) {
          fail(`${JSON.stringify(value)} is not of type 'array' (in 'prefixItems')`);
        }
        value.forEach((sub, i) => checkObjectOrBool(sub, `prefixItems[${i}]`));
        break;
      case "additionalItems":
      case "additionalProperties":
        // draft-04's meta explicitly allows boolean or schema here.
        checkObjectOrBool(value, keyword);
        break;
      case "not":
        // Known to draft-04 as a plain schema reference: objects only.
        checkObjectOnly(value, keyword);
        break;
      case "contains":
      case "propertyNames":
      case "if":
      case "then":
      case "else":
      case "unevaluatedItems":
      case "unevaluatedProperties":
        // Unknown to draft-04; draft-6+ metas accept boolean schemas.
        checkObjectOrBool(value, keyword);
        break;
      case "properties":
      case "patternProperties":
      case "definitions":
        checkSchemaMap(value, keyword, checkObjectOnly);
        break;
      case "$defs":
      case "dependentSchemas":
        checkSchemaMap(value, keyword, checkObjectOrBool);
        break;
      case "dependencies":
        if (!isType(value, "object")) {
          fail(`${JSON.stringify(value)} is not of type 'object' (in 'dependencies')`);
        }
        for (const [name, dep] of Object.entries(value)) {
          if (Array.isArray(dep)) {
            checkStringArray(dep, `dependencies.${name}`, { minItems: 1 });
          } else {
            checkObjectOnly(dep, `dependencies.${name}`);
          }
        }
        break;
      case "required":
        checkStringArray(value, keyword, { minItems: 1 });
        break;
      case "dependentRequired":
        if (!isType(value, "object")) {
          fail(`${JSON.stringify(value)} is not of type 'object' (in 'dependentRequired')`);
        }
        for (const [name, deps] of Object.entries(value)) {
          checkStringArray(deps, `dependentRequired.${name}`, {});
        }
        break;
      case "allOf":
      case "anyOf":
      case "oneOf":
        if (!Array.isArray(value) || value.length < 1) {
          fail(`${JSON.stringify(value)} is not valid for '${keyword}'`);
        }
        value.forEach((sub, i) => checkObjectOnly(sub, `${keyword}[${i}]`));
        break;
      default:
        break; // unknown keywords are permitted by every meta-schema
    }
  }
}

export function checkSchema(schema) {
  if (!isType(schema, "object")) {
    fail(`${JSON.stringify(schema)} is not a valid top-level schema`);
  }
  checkNode(schema, "schema");
}

// ErrorTree: mirrors jsonschema.exceptions.ErrorTree.
// Errors are placed in a tree keyed by their instance path; at each node the
// errors dict is keyed by the failing keyword (`error.validator`), so several
// failures of the same keyword at the same path collapse into one entry.
// `total_errors` sums the per-node dict sizes over the whole tree (context
// sub-errors of anyOf/oneOf are NOT part of the tree).

export class ErrorTree {
  constructor(errors = []) {
    this.errors = {};
    this._contents = {};
    for (const error of errors) {
      let node = this;
      for (const segment of error.path) {
        if (!Object.prototype.hasOwnProperty.call(node._contents, segment)) {
          node._contents[segment] = new ErrorTree();
        }
        node = node._contents[segment];
      }
      node.errors[error.validator] = error;
    }
    this.total_errors = this._computeTotal();
  }

  _computeTotal() {
    let total = Object.keys(this.errors).length;
    for (const child of Object.values(this._contents)) {
      total += child._computeTotal();
    }
    return total;
  }
}

